import { linkPreviewState, setLinkPreview } from './link-preview';
import { palette, type ColorKind } from './palette';
import { Prec, type EditorState } from '@codemirror/state';
import { EditorView, ViewPlugin, type ViewUpdate } from '@codemirror/view';
import { isolateHistory } from '@codemirror/commands';
import { type LinkSyntax, type GenerateNoteLink, clearFormatting, prepareLink, inspectLink, setLink, htmlTextRange, inspectInlineType, toggleInlineType, type InlineType, inspectSelection, sameTextSelection, setColor, toggleStyle, type InlineStyle } from './formatting';

export interface ToolbarOptions {
  generateNoteLink?: (state: EditorState, ...args: Parameters<GenerateNoteLink>) => ReturnType<GenerateNoteLink>;
  resolveNotePath?: (state: EditorState, target: string, syntax: LinkSyntax) => string | null;
  isLivePreview: (state: EditorState) => boolean;
  setStyleIcon?: (button: HTMLButtonElement, style: InlineStyle | 'palette' | 'paint-bucket' | 'code' | 'sigma' | 'link' | 'remove-formatting') => void;
}

export function selectionToolbar(options: ToolbarOptions) {
  const previewField = linkPreviewState(options.isLivePreview);
  return [Prec.highest(previewField), ViewPlugin.fromClass(class {
    toolbar: HTMLDivElement | null = null;
    panel: HTMLDivElement | null = null;
    pendingMouse = false;
    mouseEpoch = 0;
    bridgedClick = false;
    htmlMouse: { element: Element; source: string; range: NonNullable<ReturnType<typeof htmlTextRange>> } | null = null;
    destroyed = false;
    applying = false;
    scrollTop = 0;
    scrollLeft = 0;
    constructor(readonly view: EditorView) {
      view.dom.ownerDocument.addEventListener('mouseup', this.onMouseUp);
      view.contentDOM.addEventListener('mousedown', this.onMouseDown, true);
      view.contentDOM.addEventListener('click', this.onClick, true);
      view.dom.ownerDocument.addEventListener('mousedown', this.onOutsideMouseDown);
      view.dom.ownerDocument.addEventListener('keydown', this.onKeyDown);
      view.scrollDOM.addEventListener('scroll', this.onScroll, true);
      view.contentDOM.addEventListener('beforeinput', this.onBeforeInput);
    }
    clearPreview() {
      if (!this.destroyed && this.view.state.field(previewField).size) this.view.dispatch({ effects: setLinkPreview.of(null) });
    }
    hide = () => { this.toolbar?.remove(); this.toolbar = null; this.panel = null; this.clearPreview(); };
    cancelMouse() { this.pendingMouse = false; this.htmlMouse = null; this.bridgedClick = false; this.mouseEpoch++; }
    onBeforeInput = () => { this.cancelMouse(); this.hide(); };
    onClick = (event: MouseEvent) => {
      if (!this.bridgedClick) return;
      this.bridgedClick = false;
      // This gesture already selected source characters. Do not let the widget's
      // delayed default click replace that partial selection with the whole HTML.
      event.preventDefault(); event.stopPropagation();
    };
    onOutsideMouseDown = (event: MouseEvent) => {
      if (!this.view.contentDOM.contains(event.target as Node)) this.cancelMouse();
      if (!this.toolbar?.contains(event.target as Node)) this.hide();
    };
    onScroll = () => {
      if (this.view.scrollDOM.scrollTop !== this.scrollTop || this.view.scrollDOM.scrollLeft !== this.scrollLeft) {
        this.cancelMouse(); this.hide();
      }
    };
    onKeyDown = (event: KeyboardEvent) => {
      this.cancelMouse();
      if (event.key === 'Escape') {
        if (this.panel) { event.preventDefault(); event.stopPropagation(); this.closePalette(); this.view.focus(); this.position(); }
        else this.hide();
      }
    };
    update(update: ViewUpdate) {
      if (this.applying) return;
      if (update.docChanged || !options.isLivePreview(update.state)) this.cancelMouse();
      if (this.htmlMouse && !this.pendingMouse && !update.docChanged && update.state.selection.ranges.length === 1 &&
        sameTextSelection(this.htmlMouse.source, this.htmlMouse.range, update.state.selection.main)) {
        this.htmlMouse = null;
        this.show();
        return;
      }
      const previous = update.startState.selection, current = update.state.selection;
      const selectionChanged = !previous.eq(current);
      const markerExpansion = !update.docChanged && selectionChanged && previous.ranges.length === 1 && current.ranges.length === 1
        && sameTextSelection(update.state.doc.toString(), previous.main, current.main);
      if (update.docChanged || (selectionChanged && !markerExpansion) || !options.isLivePreview(update.state)) {
        this.hide();
        return;
      }
      if (this.toolbar) {
        if (markerExpansion) this.refreshButtons();
        this.position();
      }
    }
    onMouseDown = (event: MouseEvent) => {
      this.cancelMouse();
      if (event.button !== 0) return;
      this.scrollTop = this.view.scrollDOM.scrollTop;
      this.scrollLeft = this.view.scrollDOM.scrollLeft;
      if (options.isLivePreview(this.view.state) && event.target instanceof this.view.dom.ownerDocument.defaultView!.Element) {
        const element = event.target.closest('[contenteditable="false"]');
        if (element && this.view.contentDOM.contains(element)) {
          const source = this.view.state.doc.toString();
          const range = htmlTextRange(source, this.view.posAtDOM(element));
          if (!range || element.textContent !== range.text) return;
          this.htmlMouse = { element, source, range };
        }
      }
      this.toolbar?.remove();
      this.toolbar = null;
      this.pendingMouse = true;
    };
    onMouseUp = (event: MouseEvent) => {
      if (!this.pendingMouse || event.button !== 0) return;
      this.pendingMouse = false;
      const html = this.htmlMouse;
      const selection = this.view.dom.ownerDocument.defaultView!.getSelection();
      if (html && selection && !selection.isCollapsed && selection.rangeCount === 1) {
        this.htmlMouse = null;
        const range = selection.getRangeAt(0);
        if (html.source === this.view.state.doc.toString() && html.element.contains(range.startContainer) &&
          html.element.contains(range.endContainer) && html.element.textContent === html.range.text) {
          const prefix = this.view.dom.ownerDocument.createRange();
          prefix.selectNodeContents(html.element);
          prefix.setEnd(range.startContainer, range.startOffset);
          const start = prefix.toString().length;
          prefix.setEnd(range.endContainer, range.endOffset);
          const end = prefix.toString().length;
          if (start >= end || end > html.range.positions.length) return;
          const from = html.range.positions[start], to = html.range.positions[end - 1] + 1;
          const forward = selection.anchorNode === range.startContainer && selection.anchorOffset === range.startOffset;
          this.bridgedClick = true;
          this.view.dispatch({ selection: { anchor: forward ? from : to, head: forward ? to : from }, userEvent: 'select.pointer' });
          this.view.focus();
        } else return;
      }
      // A widget click is expanded asynchronously by the host. Never show a
      // toolbar for the previous native selection while waiting for that update.
      if (this.htmlMouse) return;
      const epoch = this.mouseEpoch;
      queueMicrotask(() => { if (!this.destroyed && epoch === this.mouseEpoch) this.show(); });
    };
    show() {
      if (!options.isLivePreview(this.view.state)) return;
      const { from, to } = this.view.state.selection.main;
      const state = inspectSelection(this.view.state.doc.toString(), from, to);
      if (!state.allowed && !state.reason && !inspectLink(this.view.state.doc.toString(), from, to).allowed) return;
      this.toolbar?.remove();
      this.scrollTop = this.view.scrollDOM.scrollTop;
      this.scrollLeft = this.view.scrollDOM.scrollLeft;
      const doc = this.view.dom.ownerDocument;
      this.toolbar = doc.createElement('div');
      this.toolbar.className = 'selection-toolbar';
      this.toolbar.style.cssText = 'position:fixed;display:flex;width:max-content;z-index:1000;visibility:hidden';
      this.toolbar.setAttribute('role', 'toolbar');
      this.toolbar.setAttribute('aria-label', '选中文字格式');
      this.toolbar.style.flexDirection = 'column';
      const row = doc.createElement('div');
      row.className = 'selection-toolbar-actions';
      row.style.display = 'flex';
      this.toolbar.append(row);
      for (const kind of ['color', 'background'] as const) {
        const button = doc.createElement('button');
        button.type = 'button';
        button.dataset.colorKind = kind;
        button.setAttribute('aria-label', kind === 'color' ? '文字颜色' : '背景颜色');
        button.setAttribute('aria-expanded', 'false');
        button.textContent = kind === 'color' ? 'A' : '▣';
        options.setStyleIcon?.(button, kind === 'color' ? 'palette' : 'paint-bucket');
        button.addEventListener('mousedown', event => event.preventDefault());
        button.addEventListener('click', () => this.openPalette(kind));
        row.append(button);
      }
      for (const action of [
        { style: 'bold', label: '加粗', glyph: 'B' },
        { style: 'italic', label: '斜体', glyph: 'I' },
        { style: 'underline', label: '下划线', glyph: 'U' },
        { style: 'strikethrough', label: '删除线', glyph: 'S' }
      ] as const) {
        const button = doc.createElement('button');
        button.type = 'button';
        button.dataset.style = action.style;
        button.setAttribute('aria-label', action.label);
        button.textContent = action.glyph;
        options.setStyleIcon?.(button, action.style);
        button.addEventListener('mousedown', event => event.preventDefault());
        button.addEventListener('click', () => {
          this.closePalette();
          const { from, to } = this.view.state.selection.main;
          const result = toggleStyle(this.view.state.doc.toString(), from, to, action.style);
          if (!result) return;
          this.applying = true;
          try {
            this.view.dispatch({ changes: result.change, selection: result.selection,
              annotations: [isolateHistory.of('full')] });
          } finally { this.applying = false; }
          this.view.focus();
          this.refreshButtons();
          this.position();
        });
        row.append(button);
      }
      for (const type of ['code', 'math'] as const) {
        const button = doc.createElement('button');
        button.type = 'button'; button.dataset.inlineType = type;
        button.setAttribute('aria-label', type === 'code' ? '行内代码' : '行内公式');
        button.textContent = type === 'code' ? '</>' : '∑';
        options.setStyleIcon?.(button, type === 'code' ? 'code' : 'sigma');
        button.addEventListener('mousedown', event => event.preventDefault());
        button.addEventListener('click', () => {
          this.closePalette();
          const { from, to } = this.view.state.selection.main;
          const result = toggleInlineType(this.view.state.doc.toString(), from, to, type);
          if (!result) return;
          this.applying = true;
          try {
            this.view.dispatch({ changes: result.change, selection: result.selection, annotations: [isolateHistory.of('full')] });
          } finally { this.applying = false; }
          this.view.focus(); this.refreshButtons(); this.position();
        });
        row.append(button);
      }
      const link = doc.createElement('button');
      link.type = 'button'; link.dataset.link = '';
      link.setAttribute('aria-label', '链接'); link.setAttribute('aria-expanded', 'false');
      link.textContent = '↗'; options.setStyleIcon?.(link, 'link');
      link.addEventListener('mousedown', event => event.preventDefault());
      link.addEventListener('click', () => this.openLink());
      row.insertBefore(link, row.querySelector('[data-style="strikethrough"]'));
      const clear = doc.createElement('button');
      clear.type = 'button'; clear.dataset.clearFormat = '';
      clear.setAttribute('aria-label', '清除格式'); clear.textContent = 'Tx';
      options.setStyleIcon?.(clear, 'remove-formatting');
      clear.addEventListener('mousedown', event => event.preventDefault());
      clear.addEventListener('click', () => {
        this.closePalette();
        const { from, to } = this.view.state.selection.main;
        const result = clearFormatting(this.view.state.doc.toString(), from, to);
        if (!result) return;
        this.applying = true;
        try {
          if (this.view.state.sliceDoc(result.change.from, result.change.to) !== result.change.insert)
            this.view.dispatch({ changes: result.change, selection: result.selection, annotations: [isolateHistory.of('full')] });
        } finally { this.applying = false; }
        this.view.focus(); this.refreshButtons(); this.position();
      });
      row.insertBefore(clear, link);
      this.refreshButtons();
      doc.body.append(this.toolbar);
      this.position();
    }
    refreshButtons() {
      const { from, to } = this.view.state.selection.main;
      const source = this.view.state.doc.toString();
      const state = inspectSelection(source, from, to);
      const clear = this.toolbar!.querySelector<HTMLButtonElement>('[data-clear-format]')!;
      clear.disabled = clearFormatting(source, from, to) === null;
      clear.title = clear.disabled ? '请完整选择可安全清除的格式；保留公式，不支持切穿结构或复杂 HTML' : '清除格式';
      const link = this.toolbar!.querySelector<HTMLButtonElement>('[data-link]')!;
      const linkState = inspectLink(source, from, to);
      link.disabled = !linkState.allowed;
      link.title = linkState.reason ?? '链接';
      link.setAttribute('aria-pressed', String(!!linkState.link));
      for (const button of this.toolbar!.querySelectorAll<HTMLButtonElement>('button[data-inline-type]')) {
        const type = button.dataset.inlineType as InlineType;
        const state = inspectInlineType(source, from, to, type);
        button.disabled = !state.allowed;
        button.setAttribute('aria-pressed', String(state.active));
        button.title = state.reason ?? button.getAttribute('aria-label')!;
      }
      for (const button of this.toolbar!.querySelectorAll<HTMLButtonElement>('button[data-color-kind]')) {
        const kind = button.dataset.colorKind as ColorKind;
        const canApply = state.allowed && palette.every(entry => setColor(source, from, to, kind, entry[kind]) !== null);
        button.disabled = !canApply;
        button.title = state.reason ?? (canApply ? button.getAttribute('aria-label')! : '此选区无法安全修改颜色');
      }
      for (const button of this.toolbar!.querySelectorAll<HTMLButtonElement>('button[data-style]')) {
        const style = button.dataset.style as InlineStyle;
        const canToggle = state.allowed && toggleStyle(source, from, to, style) !== null;
        button.setAttribute('aria-pressed', String(state[style]));
        button.disabled = !canToggle;
        button.title = state.reason ?? (canToggle ? button.getAttribute('aria-label')! : '此选区无法安全生成有效 Markdown 格式');
      }
    }
    closePalette() {
      this.clearPreview();
      this.panel?.remove(); this.panel = null;
      for (const button of this.toolbar?.querySelectorAll('[data-color-kind], [data-link]') ?? []) button.setAttribute('aria-expanded', 'false');
    }
    openLink() {
      this.closePalette();
      const { from, to } = this.view.state.selection.main;
      const state = inspectLink(this.view.state.doc.toString(), from, to);
      if (!state.allowed) return;
      const doc = this.view.dom.ownerDocument;
      const panel = doc.createElement('div'); this.panel = panel;
      panel.className = 'selection-toolbar-link'; panel.setAttribute('role', 'group');
      panel.setAttribute('aria-label', '编辑链接');
      const input = doc.createElement('input'); input.type = 'text';
      input.setAttribute('aria-label', '链接地址'); input.placeholder = 'https://… 或已有笔记完整路径.md';
      input.value = state.target.startsWith('https://') ? state.target : (state.syntax ? options.resolveNotePath?.(this.view.state, state.target, state.syntax) : null) ?? state.target;
      const error = doc.createElement('div'); error.setAttribute('role', 'alert');
      const apply = (target: string | null) => {
        const selection = this.view.state.selection.main;
        const result = setLink(this.view.state.doc.toString(), selection.from, selection.to, target, (...args) => options.generateNoteLink?.(this.view.state, ...args) ?? null);
        if (!result) {
          error.textContent = state.syntax === 'wiki' && target?.startsWith('https://')
            ? '已有 Wiki 链接只支持笔记目标；改为网页请先移除链接，再新建网页链接'
            : '地址无效、笔记不存在或格式不兼容。请输入完整 https:// 地址或已有笔记完整 .md 路径；不支持标题／块定位或不安全的结构';
          this.position(); return;
        }
        this.applying = true;
        try {
          if (this.view.state.sliceDoc(result.change.from, result.change.to) !== result.change.insert)
            this.view.dispatch({ changes: result.change, selection: result.selection, annotations: [isolateHistory.of('full')] });
        } finally { this.applying = false; }
        this.closePalette(); this.view.focus(); this.refreshButtons(); this.position();
      };
      const confirm = doc.createElement('button'); confirm.type = 'button';
      confirm.textContent = '确认'; confirm.setAttribute('aria-label', '确认链接');
      confirm.addEventListener('click', () => apply(input.value));
      const remove = doc.createElement('button'); remove.type = 'button';
      remove.textContent = '移除'; remove.setAttribute('aria-label', '移除链接'); remove.disabled = !state.link;
      remove.addEventListener('click', () => apply(null));
      input.addEventListener('keydown', event => { if (event.key === 'Enter' && !event.isComposing) { event.preventDefault(); apply(input.value); } });
      panel.append(input, confirm, remove, error); this.toolbar!.append(panel);
      this.toolbar!.querySelector('[data-link]')!.setAttribute('aria-expanded', 'true');
      const source = this.view.state.doc.toString();
      const preview = prepareLink(source, from, to);
      if (preview?.needsPreview)
        this.view.dispatch({ effects: setLinkPreview.of(preview) });
      input.focus(); this.position();
    }
    openPalette(kind: ColorKind) {
      this.closePalette();
      const doc = this.view.dom.ownerDocument;
      this.panel = doc.createElement('div');
      this.panel.className = 'selection-toolbar-palette';
      this.panel.setAttribute('role', 'group');
      this.panel.setAttribute('aria-label', kind === 'color' ? '文字颜色色板' : '背景颜色色板');
      this.toolbar!.querySelector(`[data-color-kind="${kind}"]`)!.setAttribute('aria-expanded', 'true');
      for (const entry of palette) {
        const button = doc.createElement('button');
        button.type = 'button';
        const label = entry.name === '默认' ? (kind === 'color' ? '默认文字色' : '无背景色') : entry.name;
        button.setAttribute('aria-label', label); button.title = label;
        button.textContent = 'A';
        if (kind === 'color') button.style.color = entry[kind] ?? 'var(--text-normal)';
        else button.style.backgroundColor = entry[kind] ?? 'transparent';
        button.addEventListener('mousedown', event => event.preventDefault());
        button.addEventListener('click', () => {
          const { from, to } = this.view.state.selection.main;
          const result = setColor(this.view.state.doc.toString(), from, to, kind, entry[kind]);
          if (!result) return;
          this.applying = true;
          try {
            if (this.view.state.sliceDoc(result.change.from, result.change.to) !== result.change.insert) {
              this.view.dispatch({ changes: result.change, selection: result.selection, annotations: [isolateHistory.of('full')] });
            }
          } finally { this.applying = false; }
          this.closePalette(); this.view.focus(); this.refreshButtons(); this.position();
        });
        this.panel.append(button);
      }
      this.toolbar!.append(this.panel);
      this.position();
    }
    position() {
      if (!this.toolbar) return;
      this.view.requestMeasure({
        key: this,
        read: () => this.measurePosition(),
        write: position => {
          if (this.destroyed || !this.toolbar) return;
          if (!position) { this.hide(); return; }
          const { left, top, maxWidth, maxHeight } = position;
          const constraintsChanged = this.toolbar.style.maxWidth !== maxWidth || this.toolbar.style.maxHeight !== maxHeight;
          Object.assign(this.toolbar.style, { left, top, maxWidth, maxHeight, overflow: 'auto', visibility: 'visible' });
          // A changed width limit can change toolbar dimensions; measure the resulting layout once more.
          if (constraintsChanged) this.position();
        }
      });
    }
    measurePosition() {
      if (this.destroyed || !this.toolbar) return null;
      const { from, to } = this.view.state.selection.main;
      const start = this.view.coordsAtPos(from), end = this.view.coordsAtPos(to);
      if (!start || !end) return null;
      const bounds = this.view.dom.getBoundingClientRect();
      const viewport = this.view.dom.ownerDocument.documentElement;
      const left = Math.max(0, bounds.left), right = Math.min(viewport.clientWidth, bounds.right);
      const top = Math.max(0, bounds.top), bottom = Math.min(viewport.clientHeight, bounds.bottom);
      const maxWidth = Math.max(0, right - left), maxHeight = Math.max(0, bottom - top);
      const rect = this.toolbar.getBoundingClientRect();
      const width = Math.min(rect.width, maxWidth), height = Math.min(rect.height, maxHeight);
      const x = Math.max(left, Math.min((start.left + end.right) / 2 - width / 2, right - width));
      const preferredTop = start.top - height - 8;
      const y = Math.max(top, Math.min(preferredTop >= top ? preferredTop : end.bottom + 8, bottom - height));
      return { left: `${x}px`, top: `${y}px`, maxWidth: `${maxWidth}px`, maxHeight: `${maxHeight}px` };
    }
    destroy() {
      this.destroyed = true;
      this.view.contentDOM.removeEventListener('mousedown', this.onMouseDown, true);
      this.view.contentDOM.removeEventListener('click', this.onClick, true);
      this.view.dom.ownerDocument.removeEventListener('mousedown', this.onOutsideMouseDown);
      this.view.dom.ownerDocument.removeEventListener('keydown', this.onKeyDown);
      this.view.scrollDOM.removeEventListener('scroll', this.onScroll, true);
      this.view.contentDOM.removeEventListener('beforeinput', this.onBeforeInput);
      this.hide();
      this.view.dom.ownerDocument.removeEventListener('mouseup', this.onMouseUp);
    }
  })];
}
