import { palette, type ColorKind } from './palette';
import { parser, GFM } from '@lezer/markdown';
import type { SyntaxNode } from '@lezer/common';

const markdownParser = parser.configure([GFM, {
  defineNodes: ['WikiLink', 'WikiEmbed'],
  parseInline: [{ name: 'WikiLink', before: 'Link', parse(cx, next, pos) {
    if (next !== 91 || cx.slice(pos, pos + 2) !== '[[') return -1;
    const end = cx.text.indexOf(']]', pos + 2 - cx.offset);
    if (end < 0 || /[\r\n]/.test(cx.slice(pos, end + cx.offset))) return -1;
    return cx.addElement(cx.elt(cx.char(pos - 1) === 33 ? 'WikiEmbed' : 'WikiLink', pos, end + cx.offset + 2));
  } }]
}]);
export type InlineStyle = 'bold' | 'italic' | 'strikethrough' | 'underline';
type Format = InlineStyle | ColorKind;
type Active = Record<InlineStyle, boolean> & Record<ColorKind, string | null>;
const styles: InlineStyle[] = ['bold', 'italic', 'strikethrough', 'underline'];
const styleNodes: Record<InlineStyle, string> = {
  bold: 'StrongEmphasis', italic: 'Emphasis', strikethrough: 'Strikethrough', underline: 'Underline'
};
const styleMarkers: Record<InlineStyle, string> = { bold: '**', italic: '*', strikethrough: '~~', underline: '<u>' };

function styleSpans(source: string) {
  const spans: { from: number; to: number; contentFrom: number; contentTo: number; style: Format; value?: string }[] = [];
  markdownParser.parse(source).iterate({ enter(node) {
    const style = styles.find(style => node.name === styleNodes[style]);
    if (!style) return;
    spans.push({ from: node.from, to: node.to, contentFrom: node.node.firstChild!.to,
      contentTo: node.node.lastChild!.from, style });
  } });
  const htmlStyles: Record<string, InlineStyle> = { u: 'underline', strong: 'bold', em: 'italic', s: 'strikethrough' };
  const stack: { from: number; contentFrom: number; tag: string; style: Format; value?: string }[] = [];
  for (const match of source.matchAll(/<(\/?)(span|strong|em|s|u)([^>]*)>/g)) {
    if (!match[1]) {
      let style: Format = htmlStyles[match[2]], value: string | undefined;
      if (match[2] === 'span') {
        const property = /^ style="(color|background-color): (#[0-9a-f]{6})"$/.exec(match[3]);
        if (!property) continue;
        style = property[1] === 'color' ? 'color' : 'background'; value = property[2];
        if (!palette.some(entry => entry[style as ColorKind] === value)) continue;
      } else if (match[3]) continue;
      stack.push({ from: match.index, contentFrom: match.index + match[0].length, tag: match[2], style, value });
    } else {
      const opening = stack.pop();
      if (opening?.tag === match[2] && !match[3]) spans.push({ from: opening.from, contentFrom: opening.contentFrom,
        contentTo: match.index, to: match.index + match[0].length, style: opening.style, value: opening.value });
    }
  }
  return spans;
}

export function toggleStyle(source: string, from: number, to: number, style: InlineStyle) {
  return formatSelection(source, from, to, style);
}

export function setColor(source: string, from: number, to: number, kind: ColorKind, value: string | null) {
  if (!palette.some(entry => entry[kind] === value)) return null;
  return formatSelection(source, from, to, kind, value);
}

export function clearFormatting(source: string, from: number, to: number) {
  const formulas = inlineTypeSpans(source).filter(span => span.type === 'math');
  if (formulas.some(span => span.from < to && span.to > from && !(from <= span.from && to >= span.to))) return null;
  const structures = [
    ...inlineTypeSpans(source).filter(span => span.type === 'code').map(span => ({ ...span, kind: 'code' as const })),
    ...linkSpans(source).map(span => ({ ...span, kind: 'link' as const }))
  ].filter(span => span.from < to && span.to > from && !formulas.some(math => span.from >= math.from && span.to <= math.to))
    .sort((a, b) => b.from - a.from);
  if (structures.some(span => !((from <= span.from && to >= span.to) ||
    (from === span.contentFrom && to === span.contentTo)))) return null;
  if (structures.some((span, i) => structures.slice(i + 1).some(other => other.to > span.from))) return null;
  const original = source;
  for (const span of structures) {
    const result = span.kind === 'code' ? toggleInlineType(source.slice(span.from, span.to), 0, span.to - span.from, 'code')
      : setLink(source, span.from, span.to, null);
    if (!result) return null;
    // Strip this structure only. Defer all ordinary style splitting to the final
    // pass so an enclosing wrapper cannot move the original selection endpoints.
    const text = span.kind === 'link' ? source.slice(span.contentFrom, span.contentTo) : result.change.insert;
    const delta = text.length - (span.to - span.from);
    from = from <= span.from ? from : span.from;
    to = to >= span.to ? to + delta : span.from + text.length;
    source = source.slice(0, span.from) + text + source.slice(span.to);
  }
  const result = formatSelection(source, from, to, 'plain', null, inlineTypeSpans(source).filter(span => span.type === 'math'));
  if (!result) return null;
  const updated = source.slice(0, result.change.from) + result.change.insert + source.slice(result.change.to);
  let start = 0, oldEnd = original.length, newEnd = updated.length;
  while (start < oldEnd && start < newEnd && original[start] === updated[start]) start++;
  while (oldEnd > start && newEnd > start && original[oldEnd - 1] === updated[newEnd - 1]) { oldEnd--; newEnd--; }
  return { change: { from: start, to: oldEnd, insert: updated.slice(start, newEnd) }, selection: result.selection };
}

function formatSelection(source: string, from: number, to: number, style: Format | 'plain', value: string | null = null,
  opaque: { from: number; to: number }[] = []) {
  const mask = (text: string, ranges: { from: number; to: number }[]) => {
    const chars = text.split('');
    for (const range of ranges) chars.fill('x', range.from, range.to);
    return chars.join('');
  };
  const parsedSource = opaque.length ? mask(source, opaque) : source;
  if (!inspectSelection(parsedSource, from, to).allowed) return null;
  const allSpans = styleSpans(parsedSource);
  let start = from, end = to;
  // Include enclosing/overlapping style wrappers so splitting one style preserves the others.
  let expanded: boolean;
  do {
    expanded = false;
    for (const span of allSpans) {
      if (span.from >= end || span.to <= start) continue;
      if (span.from < start || span.to > end) {
        start = Math.min(start, span.from); end = Math.max(end, span.to); expanded = true;
      }
    }
  } while (expanded);
  const spans = allSpans.filter(span => span.from < end && span.to > start);
  const chars: { value: string; selected: boolean; opaque: boolean; active: Active }[] = [];
  for (let pos = start; pos < end; pos++) {
    if (spans.some(span => (pos >= span.from && pos < span.contentFrom) || (pos >= span.contentTo && pos < span.to))) continue;
    const color = (kind: ColorKind) => spans.find(span => span.style === kind && pos >= span.contentFrom && pos < span.contentTo)?.value ?? null;
    const active = (style: InlineStyle) => spans.some(span => span.style === style && pos >= span.contentFrom && pos < span.contentTo);
    chars.push({ value: source[pos], selected: pos >= from && pos < to, opaque: opaque.some(range => pos >= range.from && pos < range.to),
      active: { bold: active('bold'), italic: active('italic'), strikethrough: active('strikethrough'), underline: active('underline'), color: color('color'), background: color('background') } });
  }
  const remove = style !== 'plain' && chars.filter(char => char.selected).every(char => char.active[style]);
  for (const char of chars) if (char.selected) {
    if (style === 'plain') char.active = { bold: false, italic: false, strikethrough: false, underline: false, color: null, background: null };
    else if (style === 'color' || style === 'background') char.active[style] = value;
    else char.active[style] = !remove;
  }
  // Emphasis cannot start or finish with whitespace.
  for (const current of styles.filter(style => style !== 'underline')) {
    for (let i = 0; i < chars.length; i++) {
      if (!chars[i].active[current]) continue;
      const begin = i;
      while (i + 1 < chars.length && chars[i + 1].active[current]) i++;
      let left = begin, right = i;
      while (left <= right && /\s/.test(chars[left].value)) chars[left++].active[current] = false;
      while (right >= left && /\s/.test(chars[right].value)) chars[right--].active[current] = false;
    }
  }
  // Longer-running styles belong outside shorter runs to avoid unnecessary delimiter splits.
  const coverage = (current: Format) => chars.filter(char => char.active[current]).length;
  const order: Format[] = ['background', 'color', 'underline', 'strikethrough', 'bold', 'italic'];
  order.sort((a, b) => coverage(b) - coverage(a));
  const html = chars.some(char => char.active.underline || char.active.color || char.active.background);
  if (html && chars.some(char => !char.opaque && /[\\&<>]/.test(char.value))) return null;
  const tags: Record<InlineStyle, string> = { bold: 'strong', italic: 'em', strikethrough: 's', underline: 'u' };
  const marker = (style: Format, active: Active, close = false) => {
    if (style === 'color' || style === 'background') return close ? '</span>'
      : `<span style="${style === 'color' ? 'color' : 'background-color'}: ${active[style]}">`;
    return html || style === 'underline' ? `<${close ? '/' : ''}${tags[style]}>` : styleMarkers[style];
  };
  let insert = '', stack: Format[] = [], anchor = -1, head = -1;
  let previous: Active = { bold: false, italic: false, strikethrough: false, underline: false, color: null, background: null };
  const outputCharacters: { pos: number; active: Active }[] = [];
  for (const char of chars) {
    const next = order.filter(current => char.active[current]);
    let common = 0;
    while (common < stack.length && stack[common] === next[common] && previous[stack[common]] === char.active[next[common]]) common++;
    for (let i = stack.length - 1; i >= common; i--) insert += marker(stack[i], previous, true);
    for (let i = common; i < next.length; i++) insert += marker(next[i], char.active);
    stack = next; previous = char.active;
    if (char.selected && anchor < 0) anchor = start + insert.length;
    outputCharacters.push({ pos: start + insert.length, active: char.active });
    insert += char.value;
    if (char.selected) head = start + insert.length;
  }
  for (const current of stack.reverse()) insert += marker(current, previous, true);
  if (anchor < 0) return null;
  const updated = source.slice(0, start) + insert + source.slice(end);
  const parsedSpans = styleSpans(opaque.length ? mask(updated, inlineTypeSpans(updated).filter(span => span.type === 'math')) : updated);
  // Reject delimiter conflicts rather than writing literal markers or losing another style.
  if (outputCharacters.some(char => order.some(current => {
    const matching = parsedSpans.filter(span => span.style === current && char.pos >= span.contentFrom && char.pos < span.contentTo);
    const actual = current === 'color' || current === 'background' ? matching.at(0)?.value ?? null : matching.length > 0;
    return char.active[current] !== actual;
  }))) return null;
  return { change: { from: start, to: end, insert }, selection: { anchor, head } };
}

export interface SelectionInspection {
  allowed: boolean;
  bold: boolean;
  italic: boolean;
  strikethrough: boolean;
  underline: boolean;
  color: string | null;
  background: string | null;
  reason?: string;
}

export function inspectSelection(source: string, from: number, to: number): SelectionInspection {
  const denied = { allowed: false, bold: false, italic: false, strikethrough: false, underline: false, color: null, background: null };
  const unsafeSelection = { ...denied, reason: '此选区包含暂不支持或无法安全修改的结构' };
  if (from < 0 || to > source.length || from >= to) return denied;
  const tree = markdownParser.parse(source);
  let paragraph: SyntaxNode | null = tree.resolveInner(from, 1);
  while (paragraph && paragraph.name !== 'Paragraph') paragraph = paragraph.parent;
  if (!paragraph || to > paragraph.to) return denied;
  for (let parent = paragraph.parent; parent; parent = parent.parent) {
    if (!['Document', 'ListItem', 'BulletList', 'OrderedList'].includes(parent.name)) return denied;
  }
  const frontmatter = /^---[ \t]*\r?\n[\s\S]*?(?:\r?\n(?:---|\.\.\.)[ \t]*(?=\r?\n|$)|$)/.exec(source);
  if (frontmatter && from < frontmatter[0].length) return denied;
  const mathText = source.split('');
  if (frontmatter) mathText.fill(' ', 0, frontmatter[0].length);
  tree.iterate({ enter(node) {
    if (['FencedCode', 'CodeBlock', 'InlineCode', 'HTMLBlock'].includes(node.name)) {
      mathText.fill(' ', node.from, node.to);
      return false;
    }
  } });
  const math = /(?<!\\)\$\$[\s\S]*?(?:\$\$|$)|(?<!\\)\$(?!\$)(?:\\.|[^$\n\\])+(?<!\\)\$/g;
  for (const match of mathText.join('').matchAll(math)) {
    if (match.index < to && match.index + match[0].length > from) return match[0].startsWith('$$') ? denied : unsafeSelection;
  }
  let unsafe = false, embedded = false;
  tree.iterate({ from: paragraph.from, to: paragraph.to, enter(node) {
    if (['HTMLTag', 'HTMLBlock'].includes(node.name) && !styleSpans(source).some(span =>
      ((node.from === span.from && node.to === span.contentFrom) ||
        (node.from === span.contentTo && node.to === span.to)))) unsafe = true;
    if (['Image', 'WikiEmbed'].includes(node.name) && node.from < to && node.to > from) embedded = true;
    if (node.from < to && node.to > from && ['InlineCode', 'Link', 'WikiLink', 'WikiEmbed', 'Image', 'Autolink'].includes(node.name)) unsafe = true;
  } });
  if (embedded) return denied;
  if (unsafe) return unsafeSelection;
  const spans = styleSpans(source);
  if (spans.some(span => span.from < to && span.to > from && (span.from < paragraph.from || span.to > paragraph.to))) return unsafeSelection;
  if (spans.some(outer => source[outer.from] === '<' && spans.some(inner =>
    source[inner.from] !== '<' && inner.from >= outer.contentFrom && inner.to <= outer.contentTo))) return unsafeSelection;
  for (const span of spans) {
    if ([from, to].some(pos => (pos > span.from && pos < span.contentFrom) || (pos > span.contentTo && pos < span.to))) return unsafeSelection;
  }
  const contentPositions = Array.from({ length: to - from }, (_, i) => from + i).filter(pos =>
    !spans.some(span => (pos >= span.from && pos < span.contentFrom) || (pos >= span.contentTo && pos < span.to)));
  const active = (style: InlineStyle) => contentPositions.length > 0 && contentPositions.every(pos =>
    spans.some(span => span.style === style && pos >= span.contentFrom && pos < span.contentTo));
  const color = (kind: ColorKind) => {
    const values = contentPositions.map(pos => spans.find(span => span.style === kind && pos >= span.contentFrom && pos < span.contentTo)?.value ?? null);
    return values.length && values.every(value => value === values[0]) ? values[0] : null;
  };
  return { allowed: true, color: color('color'), background: color('background'), bold: active('bold'), italic: active('italic'), strikethrough: active('strikethrough'), underline: active('underline') };

}

/** Source positions of literal text in a supported inline HTML wrapper. */
export function htmlTextRange(source: string, from: number) {
  const spans = styleSpans(source).filter(span => source[span.from] === '<');
  const outer = spans.filter(span => span.from === from).sort((a, b) => b.to - a.to)[0];
  if (!outer || !inspectSelection(source, outer.from, outer.to).allowed) return null;
  const markers = spans.filter(span => span.from >= outer.from && span.to <= outer.to).flatMap(span => [
    { from: span.from, to: span.contentFrom }, { from: span.contentTo, to: span.to }
  ]);
  const positions: number[] = [];
  for (let pos = outer.from; pos < outer.to; pos++) {
    if (!markers.some(marker => pos >= marker.from && pos < marker.to)) positions.push(pos);
  }
  const text = positions.map(pos => source[pos]).join('');
  // DOM and source offsets must be one-to-one; no entities or HTML whitespace folding.
  if (!text || /[&<>\\\r\n]/.test(text) || /\s{2}|[\t]/.test(text)) return null;
  return { from: outer.from, to: outer.to, text, positions };
}

/** Compare selected text positions, ignoring only complete style markers at either edge. */
export function sameTextSelection(
  source: string,
  before: { from: number; to: number },
  after: { from: number; to: number }
) {
  const marks = [...styleSpans(source), ...inlineTypeSpans(source), ...linkSpans(source)].flatMap(span => [
    { from: span.from, to: span.contentFrom }, { from: span.contentTo, to: span.to }
  ]);
  const content = ({ from, to }: { from: number; to: number }) => {
    let mark;
    while ((mark = marks.find(mark => mark.from === from && mark.to <= to))) from = mark.to;
    while ((mark = marks.find(mark => mark.to === to && mark.from >= from))) to = mark.from;
    return { from, to };
  };
  const a = content(before), b = content(after);
  return a.from < a.to && b.from < b.to && a.from === b.from && a.to === b.to;
}

export type InlineType = 'code' | 'math';

function inlineTypeSpans(source: string) {
  const spans: { type: InlineType; from: number; to: number; contentFrom: number; contentTo: number }[] = [];
  const mathText = source.split('');
  markdownParser.parse(source).iterate({ enter(node) {
    if (node.name === 'InlineCode') {
      let contentFrom = node.node.firstChild!.to, contentTo = node.node.lastChild!.from;
      const text = source.slice(contentFrom, contentTo).replace(/\n/g, ' ');
      if (text.startsWith(' ') && text.endsWith(' ') && /[^ ]/.test(text)) { contentFrom++; contentTo--; }
      spans.push({ type: 'code', from: node.from, to: node.to, contentFrom, contentTo });
    }
    if (['FencedCode', 'CodeBlock', 'InlineCode', 'HTMLBlock'].includes(node.name)) {
      mathText.fill(' ', node.from, node.to); return false;
    }
  } });
  for (const match of mathText.join('').matchAll(/(?<!\\)\$\$[\s\S]*?(?:\$\$|$)|(?<!\\)\$(?!\$)(?:\\.|[^$\n\\])+(?<!\\)\$/g)) {
    if (!match[0].startsWith('$$')) spans.push({ type: 'math', from: match.index, to: match.index + match[0].length,
      contentFrom: match.index + 1, contentTo: match.index + match[0].length - 1 });
  }
  return spans;
}

export function toggleInlineType(source: string, from: number, to: number, type: InlineType) {
  const span = inlineTypeSpans(source).find(span => span.type === type && (
    (from === span.from && to === span.to) || (from === span.contentFrom && to === span.contentTo)));
  if (span) {
    const masked = source.slice(0, span.from) + 'x'.repeat(span.to - span.from) + source.slice(span.to);
    if (!inspectSelection(masked, from, to).allowed) return null;
    let text = source.slice(span.contentFrom, span.contentTo);
    if (type === 'code') {
      text = text.replace(/\n/g, ' ');
    }
    const updated = source.slice(0, span.from) + text + source.slice(span.to);
    let encoded = false;
    markdownParser.parse(updated).iterate({ from: span.from, to: span.from + text.length, enter(node) {
      if (node.from < span.from + text.length && node.to > span.from && ['Escape', 'Entity'].includes(node.name)) encoded = true;
    } });
    if (encoded) return null;
    if (!inspectSelection(updated, span.from + text.length - text.trimStart().length, span.from + text.trimEnd().length).allowed ||
      styleSpans(updated).some(format => format.from < span.from + text.length && format.to > span.from)) return null;
    return { change: { from: span.from, to: span.to, insert: text }, selection: { anchor: span.from, head: span.from + text.length } };
  }
  if (!inspectSelection(source, from, to).allowed) return null;
  if (styleSpans(source).some(span => span.from < to && span.to > from)) return null;
  const text = source.slice(from, to);
  let encoded = false;
  markdownParser.parse(source).iterate({ from, to, enter(node) {
    if (node.from < to && node.to > from && ['Escape', 'Entity'].includes(node.name)) encoded = true;
  } });
  if (encoded || /[\n\r]/.test(text)) return null;
  if (type === 'math' && (text.trim() !== text || /[$\n\r]/.test(text) || text.endsWith('\\'))) return null;
  const marker = type === 'code' ? '`'.repeat(Math.max(0, ...Array.from(text.matchAll(/`+/g), match => match[0].length)) + 1) : '$';
  const padding = type === 'code' && (text.startsWith('`') || text.endsWith('`') || (text.startsWith(' ') && text.endsWith(' ') && /[^ ]/.test(text))) ? ' ' : '';
  const insert = marker + padding + text + padding + marker;
  const updated = source.slice(0, from) + insert + source.slice(to);
  if (!inlineTypeSpans(updated).some(span => span.type === type && span.from === from && span.to === from + insert.length)) return null;
  return { change: { from, to, insert }, selection: { anchor: from + marker.length + padding.length, head: to + marker.length + padding.length } };
}

export function inspectInlineType(source: string, from: number, to: number, type: InlineType) {
  const active = inlineTypeSpans(source).some(span => span.type === type && (
    (from === span.from && to === span.to) || (from === span.contentFrom && to === span.contentTo)));
  const allowed = toggleInlineType(source, from, to, type) !== null;
  let reason: string | undefined;
  if (!allowed) {
    let formatted = styleSpans(source).some(span => span.from < to && span.to > from);
    markdownParser.parse(source).iterate({ from, to, enter(node) {
      if (node.from < to && node.to > from && ['Link', 'WikiLink', 'Autolink'].includes(node.name)) formatted = true;
    } });
    reason = formatted ? '请先清除格式，再转换代码或公式' : '请完整选择同一种类型；代码与公式不能直接互转，特殊字符必须能安全表达';
  }
  return { allowed, active, reason };
}

export type LinkSyntax = 'markdown' | 'wiki';
type LinkSpan = { from: number; to: number; contentFrom: number; contentTo: number; target: string; syntax: LinkSyntax };
function linkSpans(source: string) {
  const spans: LinkSpan[] = [];
  markdownParser.parse(source).iterate({ enter(node) {
    if (node.name === 'WikiLink') {
      const body = source.slice(node.from + 2, node.to - 2);
      const separator = body.indexOf('|');
      spans.push({ from: node.from, to: node.to, contentFrom: separator < 0 ? node.from + 2 : node.from + 3 + separator,
        contentTo: node.to - 2, target: separator < 0 ? body : body.slice(0, separator), syntax: 'wiki' });
      return;
    }
    if (node.name !== 'Link') return;
    const children = [];
    for (let child = node.node.firstChild; child; child = child.nextSibling) children.push(child);
    const url = children.find(child => child.name === 'URL');
    const close = children.find(child => child.name === 'LinkMark' && source[child.from] === ']');
    const raw = url ? source.slice(url.from, url.to) : '';
    const target = raw.startsWith('<') ? raw.slice(1, -1) : raw;
    if (url && close && !children.some(child => child.name === 'LinkTitle')) spans.push({ from: node.from, to: node.to, contentFrom: node.from + 1, contentTo: close.from,
      target, syntax: 'markdown' });
  } });
  return spans;
}

function plainLinkContent(source: string, from: number, to: number, link?: LinkSpan) {
  const label = link ? source.slice(link.contentFrom, link.contentTo) : '';
  const editable = link ? source.slice(0, link.from) + label + source.slice(link.to) : source;
  const result = formatSelection(editable, link?.from ?? from, link ? link.from + label.length : to, 'plain');
  if (!result) return null;
  return { ...result,
    needsPreview: editable.slice(result.change.from, result.change.to) !== result.change.insert,
    change: { ...result.change, to: result.change.to + (link ? link.to - link.from - label.length : 0) }
  };
}

export function inspectLink(source: string, from: number, to: number) {
  const spans = linkSpans(source);
  const link = spans.find(span => (from <= span.from && to >= span.to && !source.slice(from, span.from).trim() && !source.slice(span.to, to).trim()) || (from === span.contentFrom && to === span.contentTo));
  const masked = link ? source.slice(0, link.from) + 'x'.repeat(link.contentFrom - link.from) +
    source.slice(link.contentFrom, link.contentTo) + 'x'.repeat(link.to - link.contentTo) + source.slice(link.to) : source;
  const cleared = plainLinkContent(source, from, to, link);
  let allowed = cleared !== null && (!link || inspectSelection(masked, from, to).allowed);
  const text = cleared?.change.insert.slice(cleared.selection.anchor - cleared.change.from, cleared.selection.head - cleared.change.from) ?? '';
  if (link && !link.target.startsWith('https://') && /[#^]/.test(link.target)) allowed = false;
  if (/[\\\r\n<>\[\]|&]/.test(text) || (link?.syntax === 'wiki' && styleSpans(source.slice(link.contentFrom, link.contentTo)).length > 0)) allowed = false;
  return { allowed, target: link?.target ?? '', syntax: link?.syntax, link,
    reason: allowed ? undefined : '请完整选择链接正文；代码、公式及不安全的结构不支持链接操作' };
}

export type GenerateNoteLink = (path: string, label: string, syntax?: LinkSyntax) => string | null;
export function setLink(source: string, from: number, to: number, target: string | null, generateNoteLink?: GenerateNoteLink) {
  const state = inspectLink(source, from, to);
  if (!state.allowed) return null;
  const cleared = plainLinkContent(source, from, to, state.link);
  if (!cleared) return null;
  const start = cleared.change.from, end = cleared.change.to;
  const left = cleared.selection.anchor - start, right = cleared.selection.head - start;
  const text = cleared.change.insert.slice(left, right);
  let insert = text, offset = 0;
  if (target !== null) {
    if (target.startsWith('https://')) {
      try { if (!new URL(target).hostname || /[\s<>\\\x00-\x1f\x7f]/.test(target)) return null; } catch { return null; }
      if (state.syntax === 'wiki') return null;
      insert = `[${text}](${target.replaceAll('(', '%28').replaceAll(')', '%29')})`; offset = 1;
    } else {
      if (!target.endsWith('.md') || /[#^|\[\]<>\\\r\n]/.test(target) || target.startsWith('/') || target.split('/').some(part => !part || part === '.' || part === '..')) return null;
      const generated = generateNoteLink?.(target, text, state.syntax);
      if (!generated) return null;
      const parsed = linkSpans(generated).find(link => link.from === 0 && link.to === generated.length);
      if (!parsed || generated.slice(parsed.contentFrom, parsed.contentTo) !== text || (state.syntax && parsed.syntax !== state.syntax)) return null;
      insert = generated; offset = parsed.contentFrom;
    }
  } else if (!state.link) return null;
  return { change: { from: start, to: end, insert: cleared.change.insert.slice(0, left) + insert + cleared.change.insert.slice(right) },
    selection: { anchor: start + left + offset, head: start + left + offset + text.length } };
}

/** A disposable presentation of a future link edit; the source document stays untouched. */
export function prepareLink(source: string, from: number, to: number) {
  const state = inspectLink(source, from, to);
  if (!state.allowed) return null;
  const result = plainLinkContent(source, from, to, state.link);
  if (!result) return null;
  const updated = source.slice(0, result.change.from) + result.change.insert + source.slice(result.change.to);
  const spans = styleSpans(updated);
  const runs: { text: string; active: Active }[] = [];
  for (let pos = result.change.from; pos < result.change.from + result.change.insert.length; pos++) {
    if (spans.some(span => pos >= span.from && pos < span.contentFrom || pos >= span.contentTo && pos < span.to)) continue;
    const active: Active = { bold: false, italic: false, strikethrough: false, underline: false, color: null, background: null };
    for (const span of spans) if (pos >= span.contentFrom && pos < span.contentTo) {
      if (span.style === 'color' || span.style === 'background') active[span.style] = span.value!;
      else active[span.style] = true;
    }
    const previous = runs.at(-1);
    if (previous && JSON.stringify(previous.active) === JSON.stringify(active)) previous.text += updated[pos];
    else runs.push({ text: updated[pos], active });
  }
  return { ...result, runs };
}
