import { StateEffect, StateField, type EditorState } from '@codemirror/state';
import { Decoration, EditorView, WidgetType, type DecorationSet } from '@codemirror/view';
import { sameTextSelection, type prepareLink } from './formatting';

type Preview = NonNullable<ReturnType<typeof prepareLink>>;
export const setLinkPreview = StateEffect.define<Preview | null>();

class LinkPreviewWidget extends WidgetType {
  constructor(readonly preview: Preview) { super(); }
  toDOM(view: EditorView) {
    const doc = view.dom.ownerDocument;
    const element = doc.createElement('span');
    element.className = 'selection-toolbar-link-preview';
    // Reset inherited theme styling; each remaining unselected run gets its own styles.
    element.style.cssText = 'font-weight:normal;font-style:normal;text-decoration:none;color:var(--text-normal);background:transparent';
    for (const { text, active } of this.preview.runs) {
      const run = doc.createElement('span'); run.textContent = text;
      if (active.bold) run.style.fontWeight = 'bold';
      if (active.italic) run.style.fontStyle = 'italic';
      run.style.textDecoration = [active.underline ? 'underline' : '', active.strikethrough ? 'line-through' : ''].filter(Boolean).join(' ') || 'none';
      if (active.color) run.style.color = active.color;
      if (active.background) run.style.backgroundColor = active.background;
      element.append(run);
    }
    return element;
  }
  ignoreEvent() { return false; }
}

/** Public, temporary decorations only: never write preview text to the file or history. */
export function linkPreviewState(isLivePreview: (state: EditorState) => boolean) {
  return StateField.define<DecorationSet>({
    create: () => Decoration.none,
    update(value, transaction) {
      if (value.size && (transaction.docChanged || !isLivePreview(transaction.state) || transaction.selection &&
        !sameTextSelection(transaction.newDoc.toString(), transaction.startState.selection.main, transaction.newSelection.main))) value = Decoration.none;
      for (const effect of transaction.effects) if (effect.is(setLinkPreview)) {
        value = effect.value ? Decoration.set([Decoration.replace({ widget: new LinkPreviewWidget(effect.value) })
          .range(effect.value.change.from, effect.value.change.to)]) : Decoration.none;
      }
      return value;
    },
    provide: field => EditorView.decorations.from(field)
  });
}
