import { Platform, Plugin, editorInfoField, editorLivePreviewField, setIcon } from 'obsidian';
import { selectionToolbar } from './toolbar';

export default class SelectionToolbarPlugin extends Plugin {
  onload() {
    if (Platform.isMobile) return;
    this.registerEditorExtension(selectionToolbar({
      isLivePreview: state => state.field(editorLivePreviewField, false) === true,
      generateNoteLink: (state, path, label, syntax) => {
        const file = this.app.vault.getFileByPath(path);
        const source = state.field(editorInfoField).file;
        if (!file || file.extension !== 'md' || !source) return null;
        if (!syntax) return this.app.fileManager.generateMarkdownLink(file, source.path, undefined, label);
        const target = this.app.metadataCache.fileToLinktext(file, source.path, syntax === 'wiki');
        return syntax === 'wiki' ? `[[${target}|${label}]]`
          : `[${label}](${encodeURI(target).replaceAll('(', '%28').replaceAll(')', '%29')})`;
      },
      resolveNotePath: (state, target, syntax) => {
        const source = state.field(editorInfoField).file;
        if (!source || !target) return null;
        let decoded: string;
        try { decoded = syntax === 'markdown' ? decodeURIComponent(target) : target; } catch { return null; }
        return this.app.metadataCache.getFirstLinkpathDest(decoded, source.path)?.path ?? null;
      },
      setStyleIcon: (button, style) => setIcon(button, style)
    }));
  }
}
